#include <iostream>
#include <string>
#include <array>

int main() {
    for (long long n : std::array<long long, 7>{0, 7, 999, 1000, -456789, 3141592, 9876543210LL}) {
        std::string text = std::to_string(n);
        std::size_t start = text[0] == '-' ? 1 : 0;
        if (start)
            std::cout << '-';
        for (std::size_t i = start; i < text.size(); i++) {
            if (i > start && (text.size() - i) % 3 == 0)
                std::cout << ',';
            std::cout << text[i];
        }
        std::cout << '\n';
    }
}
